values ('nh.skill.weekly-summary', '주간 업무 요약', '이번 주 처리한 업무 목록을 입력하면 보고서 형식의 주간 요약문을 자동 작성합니다.', 'NH Internal', 'productivity', 'skill', '[]', 'none', 'Authorization', 'admin_shared', '{}', '{"icon":"📝","prompt":"당신은 NH농협은행의 업무 보조 AI입니다. 사용자가 제공한 이번 주 업무 목록을 바탕으로 주간 업무 보고서를 작성해 주세요.\n\n**주간 업무 보고서**\n- 기간: {{이번 주 월~금}}\n- 작성자: {{이름}}\n\n### 주요 업무 실적\n{{각 업무 bullet point}}\n\n### 다음 주 예정\n{{예정 업무}}\n\n### 특이사항\n{{이슈, 리스크}}\n\n입력: {{업무 목록}}"}', 'nh_skill_weekly_summary', 'builtin://skill', true, true, 'approved', '1.0.0')
