-- ── Skill: 코드 리뷰 ─────────────────────────────────────────────────────────
insert into public.plugins (plugin_id, name, description, provider, category, extension_type, required_scopes, auth_type, auth_header_name, connection_mode, config_schema, manifest, tool_function_name, endpoint_url, is_active, enabled, approval_status, version)
values ('nh.skill.code-review', '코드 리뷰 요청', '코드 스니펫을 붙여넣으면 버그, 성능, 보안 관점의 리뷰 코멘트를 생성합니다.', 'NH Internal', 'developer', 'skill', '[]', 'none', 'Authorization', 'admin_shared', '{}', '{"icon":"🔍","prompt":"당신은 시니어 소프트웨어 엔지니어입니다. 아래 코드를 검토해 주세요.\n\n검토 항목:\n1. 버그: 잠재적 오류, 엣지케이스\n2. 성능: 불필요한 연산, N+1\n3. 보안: SQL 인젝션, XSS, 인증 누락\n4. 가독성: 변수명, 함수 분리\n5. 개선 제안\n\n코드:\n```\n{{code}}\n```\n\n각 항목에 심각도(높음/중간/낮음)를 표시해 주세요."}', 'nh_skill_code_review', 'builtin://skill', true, true, 'approved', '1.1.0')
